            new Quote { Id = "https://en.wikiquote.org/wiki/Virginia_Woolf", Text = "She had done the usual trick - been nice. She would never know him. He would never know her. Human relations were all like that, she thought, and the worst were between men and women. Inevitably these were extremely insincere.", Author = "Virginia Woolf" },
