            new Quote { Id = "https://en.wikiquote.org/wiki/Virginia_Woolf", Text = "She alone spoke the truth; to her alone could he speak it. That was the source of her everlasting attraction for him, perhaps; she was a person to whom one could say what came into one's head.", Author = "Virginia Woolf" },
