            new Quote { Id = "https://en.wikiquote.org/wiki/Virginia_Woolf", Text = "Women have served all these centuries as looking-glasses possessing the magic and delicious power of reflecting the figure of man at twice its natural size.", Author = "Virginia Woolf" },
