            new Quote { Id = "https://en.wikiquote.org/wiki/Virginia_Woolf", Text = "Though we see the same world, we see it through different eyes. Any help we can give you must be different from that you can give yourselves, and perhaps the value of that help may lie in the fact of that difference.", Author = "Virginia Woolf" },
